  end

  ---A placeholder for what is still loading: lines a text high, a block or a
  ---circle, in the skin's well colour and rounded as its controls are, with a
  ---shimmer crossing them in step — Kit's shimmer fragment
  ---(`addons/kit/shaders/shimmer.wgsl`), which Kit registers itself — held
  ---still under reduced motion.
  ---@param props kit.SkeletonProps
  ---@return kui.Node
  function M.skeleton(props)
    return component(namespace .. "/skeleton", props)
  end

  ---A box a fragment shader paints (a `fragment` node, ADR 0015): one of
  ---Kit's presets, WGSL handed over as `source`, or a fragment the host
  ---registered (`id`) — Kit registers the first two itself. Kit rounds the
  ---box by the skin's radius and keeps a shader that reads `time` still under
  ---reduced motion. With no shader, or one that does not compile
  ---(`fragment-rejected`), it is the skin's well.
  ---@param props kit.ShaderProps
  ---@return kui.Node
  function M.shader(props)
    return component(namespace .. "/shader", props)
  end

  ---A modal dialog: a title, its body and its actions; Escape and a press
  ---outside ask it to close.
  ---
  ---Your children: its list part is the body; `actions` are its buttons, at
  ---the end of its foot.
  ---@param props kit.DialogProps
  ---@param children? table
  ---@return kui.Node
  function M.dialog(props, children)
    return component(namespace .. "/dialog", props, children)
  end

  ---A panel floating beside what opened it; Escape and a press outside ask it
  ---to close.
  ---
  ---Your children: its list part is what it holds.
  ---@param props kit.PopoverProps
  ---@param children? table
  ---@return kui.Node
  function M.popover(props, children)
    return component(namespace .. "/popover", props, children)
  end

  ---A menu of items floating under what opened it.
  ---@param props kit.MenuProps
  ---@return kui.Node
  function M.menu(props)
    return component(namespace .. "/menu", props)
  end

  ---A message in a window's corner: shown for `duration` (5 s) or until
  ---dismissed (`duration = 0`), in its tone — info, success, warning or
  ---error — as a bar down its edge and its icon; it slides out as it goes.
  ---Several stack in a `toaster`.
  ---@param props kit.ToastProps
  ---@return kui.Node
  function M.toast(props)
    return component(namespace .. "/toast", props)
  end

  ---Toasts stacked in the window's corner, the newest at the foot, each
  ---sliding into the room one that goes leaves.
  ---
  ---Your children: its list part are the toasts, each placed with `inline`.
  ---@param props kit.ToasterProps
  ---@param children? table
  ---@return kui.Node
  function M.toaster(props, children)
    return component(namespace .. "/toaster", props, children)
  end

  ---A line with no axes, for a trend inline.
  ---@param props kit.SparklineProps
  ---@return kui.Node
  function M.sparkline(props)
    return component(namespace .. "/sparkline", props)
  end

  ---Lines over time with axes and a legend; `live` keeps the newest window in
  ---view.
  ---@param props kit.LineChartProps
  ---@return kui.Node
  function M.line_chart(props)
    return component(namespace .. "/line_chart", props)
  end

  ---Bars by label.
  ---@param props kit.BarChartProps
  ---@return kui.Node
  function M.bar_chart(props)
    return component(namespace .. "/bar_chart", props)
  end

  ---How a column's values fall into bins.
  ---@param props kit.HistogramProps
  ---@return kui.Node
  function M.histogram(props)
    return component(namespace .. "/histogram", props)
  end

  ---A trace waterfall: spans as bars on a time axis, nested by depth,
  ---coloured by group. The wheel and a pinch zoom about the pointer, a
  ---sideways swipe or Shift and the wheel pans, a drag on the lanes pans, and
  ---a drag on the time axis selects a range to zoom to.
  ---@param props kit.WaterfallProps
  ---@return kui.Node
  function M.waterfall(props)
    return component(namespace .. "/waterfall", props)
  end

  ---The same components under another namespace: for kit loaded twice.
  ---@param other string
  function M.at(other)
    return make(other)
  end

  return M
end

return make("kit")
